import React, { Component } from "react";
import { Modal } from "react-bootstrap";
import AwesomeSlider from "react-awesome-slider";
import AwesomeSliderStyles from "../scss/light-slider.scss";
import AwesomeSliderStyles2 from "../scss/dark-slider.scss";
import "react-awesome-slider/dist/custom-animations/scale-out-animation.css";
import RoleTypeChip from "./RoleTypeChip";
import AppFeaturesChips from "./AppFeaturesChips";


class ProjectDetailsModal extends Component {
  render() {
    if (this.props.data) {
      const technologies = this.props.data.technologies;
      const images = this.props.data.images;
      var title = this.props.data.title;
      var description = this.props.data.description;
      var overview = this.props.data.overview;
      var withCode = this.props.data.withCode;
      var url = this.props.data.url;

      // Create App Features Chips
      if (this.props.data.appFeatures) {
        var appFeatures = <AppFeaturesChips appFeatures={this.props.data.appFeatures}/>
      }

      // Create My Roles table
      if (this.props.data.myRoles) {
        var myRoles = this.props.data.myRoles.map((role, index) => (
          <tr key={index}>
            <td>{<RoleTypeChip type={role.type}/>} {role.content}</td>
          </tr>
        ))
      }

      if (this.props.data.technologies) {
        var tech = technologies.map((icons, i) => {
          return (
            <li className="list-inline-item mx-3" key={i}>
              <span>
                <div className="text-center">
                  <i className={icons.class} style={{ fontSize: "300%" }}>
                    <p className="text-center" style={{ fontSize: "30%" }}>
                      {icons.name}
                    </p>
                  </i>
                </div>
              </span>
            </li>
          );
        });
        if (this.props.data.images) {
          var img = images.map((elem, i) => {
            return <div key={i} data-src={elem} />;
          });
          var codeView = 
            <div className="col-md-10 mx-auto" style={{ paddingBottom: "50px" }}>
              <div className="slider-tab">
                <span
                  className="iconify slider-iconfiy"
                  data-icon="emojione:red-circle"
                  data-inline="false"
                  style={{ marginLeft: "5px" }}
                ></span>{" "}
                &nbsp;{" "}
                <span
                  className="iconify slider-iconfiy"
                  data-icon="twemoji:yellow-circle"
                  data-inline="false"
                ></span>{" "}
                &nbsp;{" "}
                <span
                  className="iconify slider-iconfiy"
                  data-icon="twemoji:green-circle"
                  data-inline="false"
                ></span>
              </div>
              <AwesomeSlider
                cssModule={[AwesomeSliderStyles, AwesomeSliderStyles2]}
                animation="scaleOutAnimation"
                className="slider-image"
              >
                {img}
              </AwesomeSlider>
            </div>
        }
      }
    }
    
    return (
      <Modal
        {...this.props}
        size="lg"
        aria-labelledby="contained-modal-title-vcenter"
        centered
        className="modal-inside"
      >
        <span onClick={this.props.onHide} className="modal-close">
          <i className="fas fa-times fa-3x close-icon"></i>
        </span>
        <div className="col-md-12">
          <div className="col-md-10 mx-auto">
            <h2 style={{ padding: "5px 5px 0 5px" }} className="modal-title">
              {title}
              {url ? (
                <a
                  href={url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="link-href"
                >
                  <i
                    className="devicon-github-original colored"
                    style={{ marginLeft: "10px" }}
                  ></i>
                </a>
              ) : null}
            </h2>
          </div>
          {withCode == "1" && codeView}
          <div className="col-md-10 mx-auto">
            <h3 style={{ padding: "5px 5px 0 5px" }} className="overview-title">
              Overview
            </h3>
            <p className="modal-description">{overview}</p>
          </div>
          <div className="col-md-10 mx-auto">
            <h3 style={{ padding: "5px 5px 0 5px" }}>
              My Roles
            </h3>
            <table className="my-roles-table">
              {myRoles}
            </table>
          </div>
          <div className="col-md-10 mx-auto app-features-div">
            <h3 style={{ padding: "5px 5px 0 5px" }}>
              App Features
            </h3>
            {appFeatures}
          </div>
        </div>
      </Modal>
    );
  }
}

export default ProjectDetailsModal;
